# fetch <base URL> <directory> <"sha256  path" lines>: each missing file from <base URL>/<path>.
fetch() {
  while IFS= read -r line; do
    [ -z "$line" ] && continue
    file="${line#*  }"
    if [ -s "$2/$file" ]; then continue; fi
    mkdir -p "$2/$(dirname "$file")"
    echo "downloading $file"
    curl -fsSL --retry 3 -o "$2/$file.part" "$1/${file// /%20}"
    mv "$2/$file.part" "$2/$file"
  done <<< "$3"
  (cd "$2" && shasum -a 256 -c --quiet - <<< "$(sed '/^$/d' <<< "$3")")
}
fetch "$BASE" "$DIR" "$FILES"
fetch "$REFERENCE" "$DIR/reference" "$REFERENCE_FILES"
